import { Component, createMemo, For, Show } from "solid-js";

import { ComponentID } from "#core/ui/utilities/utilities-component-id.js";
import { Layout } from "#core/ui/utilities/utilities-layout.js";
import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { CardFrame } from "#core/ui-next/components/card-frame.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { isMobile } from "#core/ui-next/services/view-experience.js";
import { useIsSmallScreen } from "#core/ui-next/utilities/layout-utilities.js";

import { CommerceCriteriaDisplay } from "#base/ui-next/screens/commerce/commerce-criteria-display.jsx";
import {
	TreasureFleetData,
	TreasureResourceData,
	useCommerceScreenContext,
} from "#base/ui-next/screens/commerce/commerce-screen-model.js";
import { TreasureConvoyProgressBar } from "#base/ui-next/screens/commerce/treasure-convoy-progress-bar.jsx";
import { ResourceTooltip } from "#base/ui-next/tooltips/resource-tooltip.jsx";

interface TreasureConvoyResourceProps {
	resource: TreasureResourceData;
	isGenerating: boolean;
	icon: string;
	cityID: ComponentID;
	isInSelectedRoute: boolean;
	index: number;
}
const TreasureConvoyCardResource: Component<TreasureConvoyResourceProps> = (props) => {
	const model = useCommerceScreenContext();
	const shouldAutoFocus = createMemo(() => props.isInSelectedRoute && props.index === 0);
	return (
		<Activatable
			class="hover\:scale-125 focus\:scale-125"
			onActivate={() => {
				model.clickUnimprovedTreasure(props.resource.location);
			}}
			disableFocus={!props.isInSelectedRoute}
			autoFocus={shouldAutoFocus()}
		>
			<div class="relative size-16 mr-1 flex items-center justify-center">
				<Icon
					class="w-full h-full"
					classList={{ "opacity-30": !props.isGenerating || !props.resource.isImproved }}
					name={props.icon}
				/>
				<Show when={props.resource.isDamaged}>
					<Icon
						class="size-10 absolute"
						name="url(blp:buildicon_warning)"
						isUrl
					/>
				</Show>
			</div>
		</Activatable>
	);
};

export interface TreasureConvoyCardProps {
	fleet: TreasureFleetData;
	inGeneratingConvoysSection: boolean;
	onFocus: () => void;
	autoFocus: boolean;
}
const TreasureConvoyCardComponent: Component<TreasureConvoyCardProps> = (props) => {
	const model = useCommerceScreenContext();
	const isSmallScreen = useIsSmallScreen();

	const isSelected = createMemo(() =>
		ComponentID.isMatch(props.fleet.cityID, model.selectedTreasureConvoyId() ?? null),
	);
	const content = (
		<CardFrame
			class={`${isMobile() ? "" : "w-128"} min-h-64 px-6 pt-6 pb-3 flex flex-col mr-6 mb-6 relative focusable-card`}
			style={isMobile() ? { width: `${Layout.pixelsToScreenPixels(isSmallScreen() ? 612 : 680)}px` } : {}}
		>
			<Activatable
				class="flex flex-row items-center mb-2"
				onActivate={() => {
					model.clickCityName(props.fleet.cityID);
				}}
				disableFocus={IsControllerActive()}
			>
				<div
					class="flex flex-row mr-3 items-center justify-center size-10 bg-center bg-cover bg-no-repeat"
					style={{ "background-image": `url("blp:banner_hex")` }}
				>
					<Icon
						class="size-8"
						name={props.fleet.cityIcon}
					/>
				</div>
				<div class="font-title text-secondary uppercase">
					<L10n.Compose text={props.fleet.cityName} />
				</div>
			</Activatable>

			<L10n.Compose text="LOC_COMMERCE_TREASURE_RESOURCES_TITLE" />
			<div class="flex flex-row w-full flex-wrap my-3">
				<For each={props.fleet.resources}>
					{(resource, index) => (
						<Show when={resource.resourceProps}>
							{(resProps) => (
								<Show
									when={props.inGeneratingConvoysSection && resource.isImproved}
									fallback={
										<Tooltip.Text text={resource.tooltip}>
											<TreasureConvoyCardResource
												resource={resource}
												isGenerating={props.inGeneratingConvoysSection}
												icon={resProps().resourceIcon}
												cityID={props.fleet.cityID}
												isInSelectedRoute={isSelected()}
												index={index()}
											/>
										</Tooltip.Text>
									}
								>
									<ResourceTooltip {...resProps()}>
										<TreasureConvoyCardResource
											resource={resource}
											isGenerating={true}
											icon={resProps().resourceIcon}
											cityID={props.fleet.cityID}
											isInSelectedRoute={isSelected()}
											index={index()}
										/>
									</ResourceTooltip>
								</Show>
							)}
						</Show>
					)}
				</For>
			</div>
			<Show
				when={props.fleet.resourceValue > 0}
				fallback={
					<div
						class="mt-2 p-4 flex flex-col"
						style={{ "background-color": "rgba(0,0,0, 0.4)" }}
					>
						<For each={props.fleet.statuses}>{(status) => <CommerceCriteriaDisplay status={status} />}</For>
					</div>
				}
			>
				<div class="text-wrap w-full pr-2 mr-2 flex-auto">{props.fleet.treasureFleetText}</div>

				<div
					class="h-1 my-1 scale-y-50"
					style={{
						"background-image": "linear-gradient(to right, rgba(77, 83, 102, 1), rgba(77, 83, 102, 0))",
					}}
				/>
				<TreasureConvoyProgressBar
					segmentCount={props.fleet.progressGoal}
					currentValue={props.fleet.progress}
				/>
				<div
					class="absolute top-0 right-3 w-12 h-20 bg-center bg-no-repeat bg-contain flex flex-col items-center"
					style={{ "background-image": `url("blp:treasure_banner")` }}
				>
					<Activatable
						onActivate={() => {
							model.clickTreasureFleet(props.fleet.cityID);
						}}
						disableFocus={IsControllerActive()}
					>
						<div
							class="size-9 mt-2 -mb-1 tint-bg-white bg-center bg-contain bg-no-repeat"
							style={{
								"background-image": `url(blp:unitflag_treasurefleet)`,
							}}
						/>
					</Activatable>
					<p>{props.fleet.resourceValue}</p>
				</div>
			</Show>
		</CardFrame>
	);

	return (
		<Activatable
			name={`${Locale.compose(props.fleet.cityName)}-Trade-Route-Card`}
			class="focusable-card-activatable"
			autoFocus={props.autoFocus}
			onActivate={() => model.setSelectedTreasureConvoyId(props.fleet.cityID)}
			disabled={!IsControllerActive() || model.selectedTreasureConvoyId() !== undefined}
			onFocus={props.onFocus}
			suppressPointerChanges
		>
			{content}
		</Activatable>
	);
};

export const TreasureConvoyCard = ComponentRegistry.register({
	name: "TreasureConvoyCard",
	createInstance: TreasureConvoyCardComponent,
});
